.dialog {
  width: min(92vw, 700px);
  max-width: 700px;
  max-height: 90vh;
  border-radius: 28px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  background: #fff;
}
.header {
  position: relative;
  padding: 20px 24px 16px 24px;
}
.close-btn {
  position: absolute;
  top: 12px;
  right: 12px;
  background: var(--white);
  border: none;
  cursor: pointer;
  border-radius: 50%;
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
}
.title {
  font-size: 24px;
  font-weight: 700;
  line-height: 1.3;
  padding-right: 40px;
  margin-bottom: 12px;
}
.reward-chip {
  display: inline-block;
  padding: 4px 12px;
  border-radius: 999px;
  background: var(--green);
  color: white;
  font-size: 13px;
  font-weight: 600;
  margin-bottom: 4px;
}
.separator {
  border: none;
  height: 1px;
  background: #e0e0e0;
  margin: 0;
}
.content {
  flex: 1;
  overflow-y: auto;
  padding: 24px;
}
.section-title {
  font-size: 20px;
  font-weight: 700;
  margin-bottom: 14px;
}
.exercise-block { margin-bottom: 20px; }
.exercise-title {
  font-size: 17px;
  font-weight: 700;
  margin-bottom: 8px;
  color: var(--green);
}
.text {
  font-size: 15px;
  line-height: 1.7;
  color: var(--grey-dark);
}
.separator:last-of-type {
  margin: 24px 0;
}
